import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import { ActivityIndicator, Image, ScrollView, Text, TouchableOpacity, View } from "react-native";

import useSocialAuth from "@/hooks/useSocialAuth";
import { authStyles } from "@/lib/authStyles";
import palette from "@/lib/theme";

type SocialProvider = "google" | "apple";

// Typed routes are regenerated by Expo during development; these are exported routes.
const SIGN_IN_HREF = "/sign-in" as Parameters<ReturnType<typeof useRouter>["push"]>[0];
const SIGN_UP_HREF = "/sign-up" as Parameters<ReturnType<typeof useRouter>["push"]>[0];

const PROVIDERS: { id: SocialProvider; label: string; logo: any }[] = [
  {
    id: "google",
    label: "Continue with Google",
    logo: require("../../assets/images/google.png"),
  },
  {
    id: "apple",
    label: "Continue with Apple",
    logo: require("../../assets/images/apple.png"),
  },
];

const AuthScreen = () => {
  const router = useRouter();
  const { loadingStrategy, handleSocialAuth } = useSocialAuth();
  const isBusy = loadingStrategy !== null;

  return (
    <ScrollView
      className="flex-1"
      style={{ flex: 1, width: "100%", backgroundColor: palette.light.background }}
      contentContainerStyle={{
        width: "100%",
        flexGrow: 1,
        justifyContent: "center",
        alignItems: "center",
        paddingHorizontal: 24,
        paddingVertical: 32,
      }}
      showsVerticalScrollIndicator={false}
    >
      <View className="mb-6 items-center" style={{ width: "100%" }}>
        <View className="mb-4 bg-primary/20 rounded-full size-16 items-center justify-center">
          <Ionicons name="bag-handle" size={32} color={palette.brand.DEFAULT} />
        </View>
        <Text className="text-3xl font-bold" style={{ color: palette.brand.DEFAULT }}>
          AfriCart
        </Text>
        <Text className="mt-1 text-sm" style={{ color: palette.light.muted }}>
          Your marketplace, made simple.
        </Text>
      </View>

      <Image
        source={require("../../assets/images/auth-image.png")}
        className="w-full max-w-80"
        resizeMode="contain"
        style={{ width: "100%", maxWidth: 320, height: 320 }}
        accessibilityLabel="Shop products from AfriCart"
      />

      <View style={{ width: "100%", maxWidth: 360, gap: 12, marginTop: 16 }}>
        {PROVIDERS.map((provider) => {
          const isLoading = loadingStrategy === `oauth_${provider.id}`;

          return (
            <TouchableOpacity
              key={provider.id}
              className="flex-row items-center justify-center bg-white border rounded-full px-6 py-3"
              style={{
                width: "100%",
                minHeight: 54,
                backgroundColor: palette.light.background,
                borderColor: palette.light.border,
                borderWidth: 1,
                borderRadius: 999,
                paddingHorizontal: 24,
                paddingVertical: 10,
                shadowColor: palette.light.shadow,
                shadowOffset: { width: 0, height: 1 },
                shadowOpacity: 0.1,
                shadowRadius: 2,
                elevation: 2,
              }}
              onPress={() => handleSocialAuth(`oauth_${provider.id}`)}
              disabled={isBusy}
              accessibilityRole="button"
              accessibilityLabel={provider.label}
              accessibilityState={{ disabled: isBusy, busy: isLoading }}
            >
              {isLoading ? (
                <ActivityIndicator size="small" color={palette.brandIcons.google} />
              ) : (
                <View className="flex-row items-center justify-center">
                  <Image
                    source={provider.logo}
                    className="size-8 mr-3"
                    resizeMode="contain"
                    style={{ width: 32, height: 32, marginRight: 12 }}
                  />
                  <Text style={{ color: palette.light.text, fontWeight: "500", fontSize: 16 }}>
                    {provider.label}
                  </Text>
                </View>
              )}
            </TouchableOpacity>
          );
        })}

        <TouchableOpacity
          onPress={() => router.push(SIGN_IN_HREF)}
          disabled={isBusy}
          style={[authStyles.primaryButton, { width: "100%", marginTop: 4, opacity: isBusy ? 0.7 : 1 }]}
          accessibilityRole="button"
          accessibilityLabel="Sign in with email"
          accessibilityState={{ disabled: isBusy }}
        >
          <Text style={authStyles.primaryButtonLabel}>Sign in with email</Text>
        </TouchableOpacity>

        <TouchableOpacity
          onPress={() => router.push(SIGN_UP_HREF)}
          disabled={isBusy}
          style={[authStyles.secondaryButton, { width: "100%", opacity: isBusy ? 0.7 : 1 }]}
          accessibilityRole="button"
          accessibilityLabel="Create account with email"
          accessibilityState={{ disabled: isBusy }}
        >
          <Text style={authStyles.secondaryButtonLabel}>Create account with email</Text>
        </TouchableOpacity>
      </View>

      <Text
        className="text-center text-xs leading-4 mt-6 px-2"
        style={{
          width: "100%",
          maxWidth: 360,
          textAlign: "center",
          color: palette.light.muted,
          fontSize: 12,
          lineHeight: 16,
          marginTop: 24,
          paddingHorizontal: 8,
        }}
      >
        By signing up, you agree to our{" "}
        <Text style={{ color: palette.light.link }}>Terms</Text>, {" "}
        <Text style={{ color: palette.light.link }}>Privacy Policy</Text>, and {" "}
        <Text style={{ color: palette.light.link }}>Cookie Use</Text>.
      </Text>
    </ScrollView>
  );
};

export default AuthScreen;
